/**
 * Ownership handover offers. At most one row per org is ever `pending`; the
 * service layer enforces that invariant, not a unique index, because a
 * resolved offer must stay queryable for history.
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { OwnershipHandover, OwnershipHandoverStatus } from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(new Date(Date.now() + 7 * MS_PER_DAY));

  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      createdAt: stamp,
      resolvedAt: null,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

export async function findPendingByOrg(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();

  return row ? toOwnershipHandover(row) : null;
}

export async function updateStatus(
  orgId: OrgId,
  id: string,
  status: OwnershipHandoverStatus,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, id),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${id} not found in org ${orgId}`);
  return toOwnershipHandover(row);
}

