/** True once `handover.expiresAt` has passed — the offer no longer counts as open. */
function isHandoverExpired(handover: OwnershipHandover): boolean {
  return new Date() >= new Date(handover.expiresAt);
}

/** Only the recorded owner — not merely someone holding the owner role — may act. */
function assertIsRecordedOwner(actor: Actor, org: Organization): void {
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:manage_ownership", {
      action: "org:manage_ownership",
      resourceKind: "organization",
      allowed: false,
      reason: "denied_by_role",
    });
  }
}

/**
 * The pending offer addressed to `actor`, lazily expiring it in storage if its
 * week has passed. Throws `"nothing_pending"` when no offer names this actor
 * and `"expired"` when it did but has lapsed.
 */
async function requirePendingForActor(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const raw = await handoverRepo.findPendingByOrg(orgId);
  if (!raw || raw.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  if (isHandoverExpired(raw)) {
    await handoverRepo.updateStatus(
      orgId,
      raw.id,
      "expired",
      toIsoTimestamp(new Date()),
    );
    throw new OwnershipHandoverError("expired");
  }

  return raw;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertIsRecordedOwner(actor, org);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const toMember = await memberRepo.findMember(orgId, toUserId);
  if (!toMember || toMember.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const existing = await handoverRepo.findPendingByOrg(orgId);
  if (existing) {
    if (!isHandoverExpired(existing)) {
      throw new OwnershipHandoverError("pending_exists");
    }
    await handoverRepo.updateStatus(
      orgId,
      existing.id,
      "expired",
      toIsoTimestamp(new Date()),
    );
  }

  const handover = await handoverRepo.insertHandover(orgId, actor.userId, toUserId);

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered workspace ownership",
    body: `${actor.userId} wants to hand ${org.name} over to you`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const handover = await requirePendingForActor(actor, orgId);
  const stamp = toIsoTimestamp(new Date());

  await handoverRepo.updateStatus(orgId, handover.id, "accepted", stamp);

  const toMember = requireFound(
    await memberRepo.findMember(orgId, handover.toUserId),
    "Member",
    handover.toUserId,
  );
  const fromMember = await memberRepo.findMember(orgId, handover.fromUserId);

  await orgRepo.transferOwnership(orgId, handover.toUserId);

  if (toMember.role !== "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, toMember.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: toMember.role,
      to: updated.role,
    });
  }

  if (fromMember && fromMember.role === "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, fromMember.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: fromMember.role,
      to: updated.role,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: handover.toUserId,
  });

  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const handover = await requirePendingForActor(actor, orgId);
  return handoverRepo.updateStatus(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertIsRecordedOwner(actor, org);

  const raw = await handoverRepo.findPendingByOrg(orgId);
  if (!raw) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  if (isHandoverExpired(raw)) {
    await handoverRepo.updateStatus(
      orgId,
      raw.id,
      "expired",
      toIsoTimestamp(new Date()),
    );
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.updateStatus(
    orgId,
    raw.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
}

export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);

  const raw = await handoverRepo.findPendingByOrg(orgId);
  if (!raw) return null;

  if (isHandoverExpired(raw)) {
    await handoverRepo.updateStatus(
      orgId,
      raw.id,
      "expired",
      toIsoTimestamp(new Date()),
    );
    return null;
  }

  return raw;
}

/**
 * If either side of an open offer leaves the workspace, the offer cannot be
 * acted on any more and is withdrawn automatically.
 */
let handoverListenersRegistered = false;

function registerHandoverListeners(): void {
  if (handoverListenersRegistered) return;
  handoverListenersRegistered = true;

  subscribe("member.removed", async (payload) => {
    const raw = await handoverRepo.findPendingByOrg(payload.orgId);
    if (!raw) return;
    if (raw.fromUserId !== payload.userId && raw.toUserId !== payload.userId) return;

    await handoverRepo.updateStatus(
      payload.orgId,
      raw.id,
      "canceled",
      toIsoTimestamp(new Date()),
    );
  });
}

registerHandoverListeners();

