import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgService from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("scratch: ownership handover", () => {
  it("full offer/accept flow", async () => {
    const tenant = await createTenant("handover-scratch", "growth");

    const handover = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(handover.status).toBe("pending");

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(OwnershipHandoverError);

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.admin,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const pending = await orgService.getPendingOwnershipHandover(
      tenant.actors.member,
      tenant.org.id,
    );
    expect(pending?.toUserId).toBe(tenant.userIds.admin);

    const org = await orgService.acceptOwnershipHandover(
      tenant.actors.admin,
      tenant.org.id,
    );
    expect(org.ownerId).toBe(tenant.userIds.admin);

    const newOwner = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const oldOwner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(newOwner?.role).toBe("owner");
    expect(oldOwner?.role).toBe("admin");

    const stillPending = await orgService.getPendingOwnershipHandover(
      tenant.actors.admin,
      tenant.org.id,
    );
    expect(stillPending).toBeNull();
  });

  it("decline and re-offer", async () => {
    const tenant = await createTenant("handover-scratch-2", "growth");
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    const declined = await orgService.declineOwnershipHandover(
      tenant.actors.admin,
      tenant.org.id,
    );
    expect(declined.status).toBe("declined");

    const again = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(again.status).toBe("pending");
  });

  it("cancel withdraws the offer", async () => {
    const tenant = await createTenant("handover-scratch-3", "growth");
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    const canceled = await orgService.cancelOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(canceled.status).toBe("canceled");

    await expect(
      orgService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(OwnershipHandoverError);
  });

  it("self-offer is refused", async () => {
    const tenant = await createTenant("handover-scratch-4", "growth");
    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.owner,
      ),
    ).rejects.toMatchObject({ reason: "self" });
  });
});

